; pi_spigot.asm - generated by gen_pi_spigot.py, do not edit by hand
; Placard CPU benchmark: Rabinowitz & Wagon spigot, 1000 digits of pi,
; centered on the screen, timed with the line read, repeated every 10 s.
; See gen_pi_spigot.py for the method, timer and memory map.
;
;     python3 placard_sim.py pi_spigot.asm --run --max-steps 2000000000 --stop-at pause --png pi.png
;
; Date: 10/16/2026

#include "placard.asm"

#addr 0x0000
reset:
    ld   main >> 8, y
    jmp  main

#addr 0x0080
font:      ; 0-9, ".", space and "s", 8 bytes each, leftmost pixel in bit 0
    #d8 0x0E, 0x11, 0x19, 0x15, 0x13, 0x11, 0x0E, 0x00
    #d8 0x04, 0x06, 0x04, 0x04, 0x04, 0x04, 0x0E, 0x00
    #d8 0x0E, 0x11, 0x10, 0x08, 0x04, 0x02, 0x1F, 0x00
    #d8 0x1F, 0x08, 0x04, 0x08, 0x10, 0x11, 0x0E, 0x00
    #d8 0x08, 0x0C, 0x0A, 0x09, 0x1F, 0x08, 0x08, 0x00
    #d8 0x1F, 0x01, 0x0F, 0x10, 0x10, 0x11, 0x0E, 0x00
    #d8 0x0C, 0x02, 0x01, 0x0F, 0x11, 0x11, 0x0E, 0x00
    #d8 0x1F, 0x10, 0x08, 0x04, 0x02, 0x02, 0x02, 0x00
    #d8 0x0E, 0x11, 0x11, 0x0E, 0x11, 0x11, 0x0E, 0x00
    #d8 0x0E, 0x11, 0x11, 0x1E, 0x10, 0x08, 0x06, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x06, 0x06, 0x00
    #d8 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    #d8 0x00, 0x00, 0x1E, 0x01, 0x0E, 0x10, 0x0F, 0x00

#addr 0x0100
emit:
    ; draw glyph [dig] at the cursor, then a "." after the first digit
    ld   [0x20], ac
    shl
    shl
    shl
    or   0x80, ac
    ld   ac, [0x26]
    ld   [0x23], ac
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ld   [0x26], ac
    inc
    ld   ac, [0x26]
    ld   x, ac
    inc
    ld   ac, [0x27]
    ld   [0x26], x
    ld   0x00, y
    ld   [y,x], ac
    ld   ac, [0x28]
    ld   [0x27], x
    ld   [0x22], y
    ld   [0x28], ac
    ld   ac, [y,x]
    ; next character cell
    ld   [0x22], ac
    add  2, ac
    ld   ac, [0x22]
    ld   [0x24], ac
    dec
    ld   ac, [0x24]
    bne  advd
    ld   0x32, ac
    ld   ac, [0x24]
    ld   [0x23], ac
    add  8, ac
    ld   ac, [0x23]
    bne  nlw
    ld   0x01, ac
    ld   ac, [0x25]
nlw:
    ld   0x80, ac
    add  [0x25], ac
    ld   ac, [0x22]
advd:
    ld   [0x21], ac
    beq  eret
    ld   0x00, ac
    ld   ac, [0x21]
    ld   0x0A, ac
    ld   ac, [0x20]
    bra  emit
eret:
    ld   [0x2A], y
    jmp  [0x29]

#addr 0x0200
div3:
    ; a[i] = remainder (x2 = 0)
    ld   [0x1A], x
    ld   [0x1B], y
    ld   [0x10], ac
    ld   ac, [y,x]
    ld   [0x1B], ac
    add  0x0E, y
    ld   [0x11], ac
    ld   ac, [y,x]
    ; step the pointer, i and the five divisors down
    ld   [0x1A], ac
    bne  pnz
    ld   [0x1B], ac
    dec
    ld   ac, [0x1B]
    ld   [0x1A], ac
pnz:
    dec
    ld   ac, [0x1A]
    ld   [0x18], ac
    dec
    bge  inz
    and  0x7F, ac
    ld   ac, [0x18]
    ld   [0x19], ac
    dec
    ld   ac, [0x19]
    ; every 128 terms: check the line read for a new frame
    ld   ret_30, ac
    ld   ac, [0x33]
    ld   ret_30 >> 8, ac
    ld   ac, [0x34]
    ld   poll >> 8, y
    jmp  poll
ret_30:
    bra  idone
inz:
    ld   ac, [0x18]
idone:
    ld   [0x38], ac
    sub  0x02, ac
    bge  dok_31
    and  0x7F, ac
    ld   ac, [0x38]
    ld   [0x39], ac
    dec
    bge  dd_32
    and  0x7F, ac
    ld   ac, [0x39]
    ld   [0x3A], ac
    dec
    ld   ac, [0x3A]
    bra  dx_33
dok_31:
    ld   ac, [0x38]
    bra  dx_33
dd_32:
    ld   ac, [0x39]
dx_33:
    ld   [0x3B], ac
    sub  0x04, ac
    bge  dok_34
    and  0x7F, ac
    ld   ac, [0x3B]
    ld   [0x3C], ac
    dec
    bge  dd_35
    and  0x7F, ac
    ld   ac, [0x3C]
    ld   [0x3D], ac
    dec
    ld   ac, [0x3D]
    bra  dx_36
dok_34:
    ld   ac, [0x3B]
    bra  dx_36
dd_35:
    ld   ac, [0x3C]
dx_36:
    ld   [0x3E], ac
    sub  0x08, ac
    bge  dok_37
    and  0x7F, ac
    ld   ac, [0x3E]
    ld   [0x3F], ac
    dec
    bge  dd_38
    and  0x7F, ac
    ld   ac, [0x3F]
    ld   [0x40], ac
    dec
    ld   ac, [0x40]
    bra  dx_39
dok_37:
    ld   ac, [0x3E]
    bra  dx_39
dd_38:
    ld   ac, [0x3F]
dx_39:
    ld   [0x41], ac
    sub  0x10, ac
    bge  dok_40
    and  0x7F, ac
    ld   ac, [0x41]
    ld   [0x42], ac
    dec
    bge  dd_41
    and  0x7F, ac
    ld   ac, [0x42]
    ld   [0x43], ac
    dec
    ld   ac, [0x43]
    bra  dx_42
dok_40:
    ld   ac, [0x41]
    bra  dx_42
dd_41:
    ld   ac, [0x42]
dx_42:
    ld   [0x44], ac
    sub  0x20, ac
    bge  dok_43
    and  0x7F, ac
    ld   ac, [0x44]
    ld   [0x45], ac
    dec
    bge  dd_44
    and  0x7F, ac
    ld   ac, [0x45]
    ld   [0x46], ac
    dec
    ld   ac, [0x46]
    bra  dx_45
dok_43:
    ld   ac, [0x44]
    bra  dx_45
dd_44:
    ld   ac, [0x45]
dx_45:
    ; loop while i > 1
    ld   [0x19], ac
    bne  again
    ld   [0x18], ac
    sub  1, ac
    beq  last
again:
    ld   inner >> 8, y
    jmp  inner
last:
    ld   last_i >> 8, y
    jmp  last_i

#addr 0x0300
div2:
    ; k = 3
    ld   [0x10], ac
    sub  [0x41], ac
    bge  n0_10
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_11
n0_10:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_11:
    sub  [0x42], ac
    bge  n1_12
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_13
n1_12:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_13:
    sub  [0x43], ac
    blt  ns_14
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x08, ac
    ld   ac, [0x15]
ns_14:
    ; k = 2
    ld   [0x10], ac
    sub  [0x3E], ac
    bge  n0_15
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_16
n0_15:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_16:
    sub  [0x3F], ac
    bge  n1_17
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_18
n1_17:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_18:
    sub  [0x40], ac
    blt  ns_19
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x04, ac
    ld   ac, [0x15]
ns_19:
    ; k = 1
    ld   [0x10], ac
    sub  [0x3B], ac
    bge  n0_20
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_21
n0_20:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_21:
    sub  [0x3C], ac
    bge  n1_22
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_23
n1_22:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_23:
    sub  [0x3D], ac
    blt  ns_24
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x02, ac
    ld   ac, [0x15]
ns_24:
    ; k = 0
    ld   [0x10], ac
    sub  [0x38], ac
    bge  n0_25
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
    dec
    bra  m0_26
n0_25:
    ld   ac, [0x13]
    ld   [0x11], ac
m0_26:
    sub  [0x39], ac
    bge  n1_27
    and  0x7F, ac
    ld   ac, [0x14]
    ld   [0x12], ac
    dec
    bra  m1_28
n1_27:
    ld   ac, [0x14]
    ld   [0x12], ac
m1_28:
    sub  [0x3A], ac
    blt  ns_29
    ld   ac, [0x12]
    ld   [0x14], ac
    ld   ac, [0x11]
    ld   [0x13], ac
    ld   ac, [0x10]
    ld   [0x15], ac
    or   0x01, ac
    ld   ac, [0x15]
ns_29:
    ld   div3 >> 8, y
    jmp  div3

#addr 0x0400
tsync:
    ; start the timer at the top of a frame: wait for the line read to wrap
    ld   ret_1, ac
    ld   ac, [0x33]
    ld   ret_1 >> 8, ac
    ld   ac, [0x34]
    ld   poll >> 8, y
    jmp  poll
ret_1:
sync:
    ld   0x00, ac
    ld   ac, [0x2F]
    ld   ret_2, ac
    ld   ac, [0x33]
    ld   ret_2 >> 8, ac
    ld   ac, [0x34]
    ld   poll >> 8, y
    jmp  poll
ret_2:
    ld   [0x2F], ac
    beq  sync
    ld   ret_3, ac
    ld   ac, [0x33]
    ld   ret_3 >> 8, ac
    ld   ac, [0x34]
    ld   tclear >> 8, y
    jmp  tclear
ret_3:
    ; a[i] = 2: low limb pages = 2, high limb pages = 0
    ld   0x08, ac
    ld   ac, [0x28]
fill_pg:
    ld   ret_4, ac
    ld   ac, [0x33]
    ld   ret_4 >> 8, ac
    ld   ac, [0x34]
    ld   poll >> 8, y
    jmp  poll
ret_4:
    ld   [0x28], y
    clr  x
fill_b:
    ld   0x02, [y,x]
    ld   [0x28], ac
    add  0x0E, y
    ld   0x00, [y,x]
    ld   [0x28], y
    ld   x, ac
    inc
    ld   ac, x
    bne  fill_b
    ld   [0x28], ac
    inc
    ld   ac, [0x28]
    sub  0x16, ac
    bne  fill_pg
    ; output state
    ld   0x00, ac
    ld   ac, [0x1C]
    ld   0x00, ac
    ld   ac, [0x1D]
    ld   0x01, ac
    ld   ac, [0x1E]
    ld   0x01, ac
    ld   ac, [0x21]
    ld   0x7C, ac
    ld   ac, [0x22]
    ld   0xB8, ac
    ld   ac, [0x23]
    ld   0x00, ac
    ld   ac, [0x25]
    ld   0x34, ac
    ld   ac, [0x24]
    ld   0x68, ac
    ld   ac, [0x2B]
    ld   0x07, ac
    ld   ac, [0x2C]
    ; ---- one digit per pass ----
outer:
    ld   0x00, ac
    ld   ac, [0x15]
    ld   0x06, ac
    ld   ac, [0x18]
    ld   0x1A, ac
    ld   ac, [0x19]
    ld   0x06, ac
    ld   ac, [0x1A]
    ld   0x15, ac
    ld   ac, [0x1B]
    ld   0x0B, ac
    ld   ac, [0x38]
    ld   0x34, ac
    ld   ac, [0x39]
    ld   0x00, ac
    ld   ac, [0x3A]
    ld   0x16, ac
    ld   ac, [0x3B]
    ld   0x68, ac
    ld   ac, [0x3C]
    ld   0x00, ac
    ld   ac, [0x3D]
    ld   0x2C, ac
    ld   ac, [0x3E]
    ld   0x50, ac
    ld   ac, [0x3F]
    ld   0x01, ac
    ld   ac, [0x40]
    ld   0x58, ac
    ld   ac, [0x41]
    ld   0x20, ac
    ld   ac, [0x42]
    ld   0x03, ac
    ld   ac, [0x43]
    ld   0x30, ac
    ld   ac, [0x44]
    ld   0x41, ac
    ld   ac, [0x45]
    ld   0x06, ac
    ld   ac, [0x46]
    ld   inner >> 8, y
    jmp  inner

#addr 0x04D5
tclear:
    ; timer = 0, frame addend = 16800 us, step addend = 128 us
    ld   0x50, x
tcl:
    ld   0x00, [x]
    ld   x, ac
    inc
    ld   ac, x
    sub  0x79, ac
    bne  tcl
    ld   8, ac
    ld   ac, [0x62]
    ld   6, ac
    ld   ac, [0x63]
    ld   1, ac
    ld   ac, [0x64]
    ld   8, ac
    ld   ac, [0x70]
    ld   2, ac
    ld   ac, [0x71]
    ld   1, ac
    ld   ac, [0x72]
    ld   [0x34], y
    jmp  [0x33]

#addr 0x0500
last_i:
    ; x = 10 * a[1] + q, a[1] = x mod 10, q = x div 10 (x <= 110)
    ld   0x08, y
    ld   0x01, x
    ld   [y,x], ac
    shl
    ld   ac, [0x13]
    shl
    shl
    add  [0x13], ac
    add  [0x15], ac
    ld   ac, [0x10]
    clr  ac
    ld   ac, [0x15]
d10:
    ld   [0x10], ac
    sub  10, ac
    blt  d10done
    ld   ac, [0x10]
    ld   [0x15], ac
    inc
    ld   ac, [0x15]
    bra  d10
d10done:
    ld   [0x10], ac
    ld   ac, [y,x]
    ; predigit handling
    ld   [0x15], ac
    sub  9, ac
    bne  not9
    ld   [0x1D], ac
    inc
    ld   ac, [0x1D]
    bra  next
not9:
    sub  1, ac
    bne  normal
    ; q = 10: held digit + 1, then the held 9s become 0s
    ld   [0x1C], ac
    inc
    ld   ac, [0x20]
    ld   ret_46, ac
    ld   ac, [0x29]
    ld   ret_46 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_46:
    ld   0x00, ac
    ld   ac, [0x1F]
    ld   0x00, ac
    ld   ac, [0x1C]
    bra  flush
normal:
    ld   [0x1E], ac
    bne  nofirst
    ld   [0x1C], ac
    ld   ac, [0x20]
    ld   ret_47, ac
    ld   ac, [0x29]
    ld   ret_47 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_47:
nofirst:
    ld   0x00, ac
    ld   ac, [0x1E]
    ld   [0x15], ac
    ld   ac, [0x1C]
    ld   0x09, ac
    ld   ac, [0x1F]
flush:
    ld   [0x1D], ac
    beq  next
    dec
    ld   ac, [0x1D]
    ld   [0x1F], ac
    ld   ac, [0x20]
    ld   ret_48, ac
    ld   ac, [0x29]
    ld   ret_48 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_48:
    bra  flush
next:
    ; digits left (base 128 counter)
    ld   [0x2B], ac
    dec
    bge  jok
    and  0x7F, ac
    ld   ac, [0x2B]
    ld   [0x2C], ac
    dec
    ld   ac, [0x2C]
    bra  jtest
jok:
    ld   ac, [0x2B]
jtest:
    ld   [0x2B], ac
    or   [0x2C], ac
    beq  finish
    ld   outer >> 8, y
    jmp  outer
finish:
    ld   [0x1C], ac
    ld   ac, [0x20]
    ld   ret_49, ac
    ld   ac, [0x29]
    ld   ret_49 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_49:
    ld   stop >> 8, y
    jmp  stop

#addr 0x05C0
dadd:
    ; timer digits at 0x50 += addend digits at 0x50 + [doff], decimal
    clr  ac
    ld   ac, [0x31]
    ld   0x50, x
dl:
    ld   [x], ac
    add  [0x31], ac
    ld   ac, [0x32]
    ld   x, ac
    add  [0x30], ac
    ld   ac, x
    ld   [x], ac
    add  [0x32], ac
    ld   ac, [0x32]
    ld   x, ac
    sub  [0x30], ac
    ld   ac, x
    ld   [0x32], ac
    sub  10, ac
    blt  dlt
    ld   ac, [x]
    ld   1, ac
    bra  dn
dlt:
    ld   [0x32], ac
    ld   ac, [x]
    clr  ac
dn:
    ld   ac, [0x31]
    ld   x, ac
    inc
    ld   ac, x
    sub  0x59, ac
    bne  dl
    ld   [0x36], y
    jmp  [0x35]

#addr 0x0600
inner:
    ; a[i] -> al, ah
    ld   [0x1A], x
    ld   [0x1B], y
    ld   [y,x], ac
    ld   ac, [0x16]
    ld   [0x1B], ac
    add  0x0E, y
    ld   [y,x], ac
    ld   ac, [0x17]
