    ld   0x2E, y
    ld   [y,x], ac
    ld   ac, [0x10]
    ld   0x41, y
    ld   [y,x], ac
    ld   ac, [0x11]
    ld   [0x17], x
    ld   [y,x], ac
    ld   ac, [0x12]
    ld   0x2E, y
    ld   [y,x], ac
    ld   ac, [0x13]
