    ld   [0x15], ac
    add  0x24, y
    ld   [0x18], x
    ld   [y,x], ac
    add  [0x10], ac
    bge  qi0
    and  0x7F, ac
    ld   ac, [0x10]
    ld   [0x11], ac
    inc
    ld   ac, [0x11]
    bra  qi1
qi0:
    ld   ac, [0x10]
qi1:
    ld   [0x19], x
    ld   [y,x], ac
    add  [0x13], ac
    bge  qi2
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x12], ac
    inc
    ld   ac, [0x12]
    bra  qi3
qi2:
    ld   ac, [0x13]
qi3:
