    ld   0x00, ac
    ld   ac, [0x15]
    ; k = 4
    ld   [0x10], ac
    sub  [0x44], ac
    bge  n0_5
    and  0x7F, ac
    ld   ac, [0x13]
    ld   [0x11], ac
