#addr 0x06B6
stop:
    ; stop the timer: whole frames are counted, add the 128 us steps since
    ; the top of this frame
    ld   ret_51, ac
    ld   ac, [0x33]
    ld   ret_51 >> 8, ac
    ld   ac, [0x34]
    ld   poll >> 8, y
    jmp  poll
ret_51:
    ld   [0x2E], ac
    sub  124, ac
    ld   ac, [0x28]
    ld   0x20, ac
    ld   ac, [0x30]
part:
    ld   [0x28], ac
    beq  pdone
    dec
    ld   ac, [0x28]
    ld   ret_52, ac
    ld   ac, [0x35]
    ld   ret_52 >> 8, ac
    ld   ac, [0x36]
    ld   dadd >> 8, y
    jmp  dadd
ret_52:
    bra  part
pdone:
    ld   show >> 8, y
    jmp  show

#addr 0x06E6
clr_m:
    ; mode bytes 4A00-4BFF = 0 (1 bpp)
    ld   0x4A, y
    clr  x
clr_m0:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  clr_m0
    ld   0x4B, y
clr_m1:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  clr_m1
    ld   tsync >> 8, y
    jmp  tsync

#addr 0x0700
show:
    ; "SSS.SSS s" centered below the digits, leading zeros as spaces
    ld   0xA9, ac
    ld   ac, [0x22]
    ld   0x60, ac
    ld   ac, [0x23]
    ld   0x00, ac
    ld   ac, [0x24]
    ld   0x00, ac
    ld   ac, [0x21]
    ; leading zeros of the seconds become spaces (the timer is cleared next)
    ld   [0x58], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x58]
    ld   [0x57], ac
    bne  sh1
    ld   11, ac
    ld   ac, [0x57]
sh1:
    ; digits 8 down to 3, with "." after the ones digit
    ld   0x58, ac
    ld   ac, [0x37]
shlp:
    ld   [0x37], x
    ld   [x], ac
    ld   ac, [0x20]
    ld   ret_53, ac
    ld   ac, [0x29]
    ld   ret_53 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_53:
    ld   [0x37], ac
    sub  0x56, ac
    bne  shnd
    ld   10, ac
    ld   ac, [0x20]
    ld   ret_54, ac
    ld   ac, [0x29]
    ld   ret_54 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_54:
shnd:
    ld   [0x37], ac
    dec
    ld   ac, [0x37]
    sub  0x52, ac
    bne  shlp
    ld   0x0B, ac
    ld   ac, [0x20]
    ld   ret_55, ac
    ld   ac, [0x29]
    ld   ret_55 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_55:
    ld   0x0C, ac
    ld   ac, [0x20]
    ld   ret_56, ac
    ld   ac, [0x29]
    ld   ret_56 >> 8, ac
    ld   ac, [0x2A]
    ld   emit >> 8, y
    jmp  emit
ret_56:
    ld   pause >> 8, y
    jmp  pause

#addr 0x0779
poll:
    ; read the line read (V9:V2, 124-255) and add one frame to the timer
    ; when it went down.  cur - last - 96 >= 0 means it wrapped, as long as
    ; polls are less than 95 steps (380 lines) apart.  Uses y and x.
    ld   0x50, y
    ld   [y,x], ac
    ld   ac, [0x2D]
    sub  [0x2E], ac
    sub  96, ac
    blt  pnw
    ld   0x01, ac
    ld   ac, [0x2F]
    ld   0x10, ac
    ld   ac, [0x30]
    ld   ret_50, ac
    ld   ac, [0x35]
    ld   ret_50 >> 8, ac
    ld   ac, [0x36]
    ld   dadd >> 8, y
    jmp  dadd
ret_50:
pnw:
    ld   [0x2D], ac
    ld   ac, [0x2E]
    ld   [0x34], y
    jmp  [0x33]

#addr 0x07A0
pause:
    ; wait 10 s on the timer, then run the test again
    ld   ret_57, ac
    ld   ac, [0x33]
    ld   ret_57 >> 8, ac
    ld   ac, [0x34]
    ld   tclear >> 8, y
    jmp  tclear
ret_57:
pw:
    ld   ret_58, ac
    ld   ac, [0x33]
    ld   ret_58 >> 8, ac
    ld   ac, [0x34]
    ld   poll >> 8, y
    jmp  poll
ret_58:
    ld   [0x57], ac
    sub  1, ac
    bne  pw
shown:
    ld   main >> 8, y
    jmp  main

#addr 0x07C2
main:
    ; clear video RAM 6000-FFFF (pixels off)
    ld   0x60, ac
    ld   ac, [0x28]
clr_pg:
    ld   [0x28], y
    clr  x
clr_b:
    ld   0x00, [y,x]
    ld   x, ac
    inc
    ld   ac, x
    bne  clr_b
    ld   [0x28], ac
    inc
    ld   ac, [0x28]
    bne  clr_pg
    ld   clr_m >> 8, y
    jmp  clr_m

